@startuml

class Person {
  + personID : int
  + phoneNumber : string
  + keywords : string[]
}

class ResearchInstitution {
  + institutionCode : int
}

class ScientificArticle {
  + DOI : string
  + title : string
}

class PeerReviewedPaper extends ScientificArticle {
  + citationCount : int
}

class TechnicalReport extends ScientificArticle {
}

class Publisher {
  + name : string
}

class Journal {
  + name : string
  + impactFactor : float
}

class AuthorPosition {
  + position : int
}

Person "1" -- "1" ResearchInstitution : works for

Person "1" -- "0..*" ScientificArticle : author
(ScientificArticle, Person) -- "1" AuthorPosition

Person "1" -- "0..*" PeerReviewedPaper : reviewer

ResearchInstitution "1" -- "0..*" TechnicalReport : publishes

Publisher "1" -- "1..*" Journal : publishes

ResearchInstitution "0..*" -- "0..*" Journal : subscribes

@enduml

